def find_password_length(s):
    length = len(s)
    for length in range(1, length // 2 + 1):
        if length % 2 == 1:
            odd_length_phrase = length * "h"
        else:
            odd_length_phrase = length // 2 * "h" + "b"
        for index in range(length):
            part = s[index:index + length]
            if part == odd_length_phrase:
                return length
    return 0

def find_complementary_part_size(s):
    for length in range(1, len(s) // 2 + 1):
        if len(s) % length == 0 or s[-length:] == "eh":
            return length
    return 0

def solve_ciphered_password(ciphertext):
    words = ciphertext.split(" ")
    common_middle_length = -1
    for word in words:
        middle_length = find_complementary_part_size(word)
        if middle_length is not None:
            common_middle_length = max(common_middle_length, middle_length)
    return common_middle_length

def solve(s):
    l = solve_ciphered_password(s)
    return l

