def max_points(n, m, p, candies, stones):
    # Initialize DP table
    dp = [[0] * (p + 1) for _ in range(n + 1)]

    # Fill the DP table
    for a in range(1, n + 1):
        for b in range(1, m + 1):
            for r in range(1, p + 1):
                if a - r >= 0 and b - r >= 0:
                    dp[a][r] = max(dp[a][r], dp[a - r][r] + sum(candies[:a - r] + stones[:b - r]) % p)
                if b - r >= 0:
                    dp[a][r] = max(dp[a][r], dp[a][r - 1] + sum(stones[:b - r]) % p)

    # Find the maximum points Gerald can earn
    max_points = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            max_points = max(max_points, dp[i][j])

    # Construct the optimal strategy string
    strategy = ''
    for i in range(n + m - 2):
        if i % 2 == 0:
            strategy += 'C'
        else:
            strategy += 'S'

    return max_points, strategy

