        for u in tree1:
            for v in V[u]:
                t1 = u
                t2 = v
        tree1.remove(t1)
        tree2.remove(t2)
        tree1.append(t2)
        tree2.append(t1)

    # Perform the depth-first search
    def dfs(root, visited):
