def treePathCounts(n):
    # Initialize counts array
    counts = [0] * (n + 1)
    # Make tree
    edges = []
    for i in range(1, n + 1):
        edges.append((i - 1, i))
    # Build tree by lazy adding edges and lazy presorting
    for _ in range(2 * (n - 1) - 1):
        edges.sort()
        for i in range(n):
            if i > 0 and (i - 1, i) in edges:
                edges.remove((i - 1, i))
                edges.insert(2 * i, (i - 1, i))
            if i < n - 1 and (i + 1, i) in edges:
                edges.remove((i + 1, i))
                edges.insert(2 * i + 2, (i + 1, i))
    for edge in edges:
        if edge[0] == edge[1]:
            counts[0] += 1
    for i in range(2, n + 1):
        counts[i] += counts[i - 2]
    return counts

