from typing import List

def max_k_valid_paths(n: int) -> List[int]:
    path_count = defaultdict(int)
    for i in range(1, 1 << n):
        path_sum = 0
        for j in range(n):
            if (i >> j) & 1:
                path_sum += 1
        path_count[path_sum] += 1
    for i in range(n + 1):
        path_count[i] += path_count[i - 1]
    return [path_count[i] for i in range(n + 1)]

