def is_valid_triangle(red_points, blue_points):
    for p1, p2, p3 in combinations(red_points + blue_points, 3):
        if abs(p1[0] - p2[0]) >= abs(p1[1] - p3[1]) and abs(p1[1] - p2[1]) >= abs(p1[0] - p3[0]) and abs(p1[1] - p3[1]) > 0:
            return True
    return False

def count_valid_triangles(red_points, blue_points):
    valid_triangles = 0
    red_points = sorted(red_points)
    for i in range(len(red_points) - 2):
        for j in range(i + 1, len(red_points) - 1):
            for k in range(j + 1, len(red_points)):
                if i > 0 and abs(red_points[j][0] - red_points[i][0]) > abs(red_points[j][1] - red_points[i][1]):
                    break
                if j > 0 and abs(red_points[k][0] - red_points[j][0]) > abs(red_points[k][1] - red_points[j][1]):
                    break
                if k > 0 and abs(red_points[i][0] - red_points[k][0]) > abs(red_points[k][1] - red_points[k][1]):
                    break
                if is_valid_triangle([red_points[i], red_points[j], red_points[k]], blue_points):
                    valid_triangles += 1
    return valid_triangles

