from collections import defaultdict

def max_k_valid_paths(n):
    tree = defaultdict(list)
    for _ in range(n-1):
        u, v = map(int, input().split())
        tree[u-1].append(v-1)
        tree[v-1].append(u-1)

    def max_paths(cur, prev, level, depth_g_last, depth_mode, val_cnt, path_cnt, k_mode):
        if level >= k_mode:
            return 0, val_cnt, path_cnt
        M = 0
        for nxt in tree[cur]:
            if nxt != prev:
                M, _, M = max_paths(nxt, cur, level+1, depth_g, depth_mode, val_cnt, path_cnt, k_mode)
                if depth_mode:
                    if M + 1 == val_cnt:
                        val_cnt = M + depth_last - depth_cur + 1
                    else:
                        val_cnt = depth_g - depth_last + level + 1
                        if depth_last - depth_cur + 1 > val_cnt[-1]:
                            val_cnt.pop()
                            val_cnt.append(depth_last - depth_cur + 1)
                    if level+1 <= k_mode - M:
                        path_cnt = max(path_cnt, M + 1)
                    elif level + 1 < k_mode - M:
                        while path_cnt > M + level:
                            path_cnt = M + level + 1

        return val_cnt, path_cnt, M if depth_mode else max(M, val_cnt)

    ans = []
    for mode in range(2, n+1):
        depth_g, depth_last, depth_cur = 0, 0, 0
        val_cnt = []
        path_cnt = []
        M, _, M = max_paths(-1, -1, 0, depth_g, True, val_cnt, path_cnt, mode)
        ans.append(M)
        _, M_paths, _ = max_paths(-1, -1, 0, depth_g, False, val_cnt, path_cnt, mode)
        ans.append(M_paths)
    return ans

