from itertools import combinations

def find_non_separated_triangles(red_points, blue_points):
    # Sort points horizontally to facilitate checking vertical alignment
    sorted_red = sorted(red_points, key=lambda x: x[0])
    sorted_blue = sorted(blue_points, key=lambda x: x[0])

    # Create a set of all intersections between red points' vertical projections
    intersections = set()
    for i in range(len(sorted_red)):
        for j in range(i + 1, len(sorted_red)):
            if sorted_red[i][0] == sorted_red[j][0]:
                intersections.add((sorted_red[i][0], sorted_red[~i][0]))
            else:
                intersections.add((sorted_red[i][1], sorted_red[j][1]))
                intersections.add((sorted_red[j][1], sorted_red[i][1]))

    # Collect all unique (red, blue) intersections found
    points_on_grid = set()
    for red_i in range(len(sorted_red)):
        for red_j in range(0, len(sorted_red) - red_i):
            for blue_i in range(len(sorted_blue)):
                for blue_j in range(0, len(sorted_blue) - blue_i):
                    if sorted_blue[blue_i][0] == sorted_blue[blue_j][0] and \
                       sorted_red[sorted_red.index(sorted_red[i])][1] == sorted_red[sorted_red.index(sorted_red[~i])][1]:
                        points_on_grid.add((sorted_red[sorted_red.index(sorted_red[i])][0] - 1, sorted_blue[blue_i][1] - 1))

    # Define a function to check if two points are horizontal neighbors
    def is_horizontal_neighbor(a, b):
        if a[0] == b[0]:
            return True
        return False

    valid_triangles = 0

    for red_red_pairs in combinations(red_points, 2):
        if not is_horizontal_neighbor(red_red_pairs[0], red_red_pairs[1]):
            for blue_cliques in combinations(blue_points, 2):
                triangle = tuple(filter(lambda pair: pair[0] in red_red_pairs and pair[1] in blue_cliques, combinations(sorted_blue, 2)))
                if all(not is_horizontal_neighbor(triangle_cnt[0], triangle_cnt[1]) for triangle_cnt in triangle) and len(triangle) == 2:
                    valid_triangles += 1

    return valid_triangles

