from collections import deque

def calculate_score(c, v):
    values = [0] * len(c)
    prev_values = []
    stack = deque()

    for i, (c_i, v_i) in enumerate(zip(c, v)):
        values[i] = v_i
        while stack and stack[-1] < values[i]:
            prev_values.append(stack.pop())
        if not stack or stack[-1] < values[i]:
            stack.append(values[i])
    return sum(values) - sum(prev_values)

