    def sub(a: float, b: float) -> float:
        return a[0] - b[0], a[1] - b[1]

    # Sort segments by start point
    segments = []
    for p, next_p in zip(original, original[1:]):
        segments.append([(triangle_area(p, next_p[0], next_p[1]), p, next_p, p[0], p[1])])
        segments.append([(triangle_area(p, next_p[0], next_p[1]), next_p)])

    # Use multi-cmd algo for lines intersections
