def max_points(n, m, p, candies, stones):
    # Calculate gcd for faster solution
    import math
    gcd = math.gcd(n, m)

    # Calculate Bob (Mike) points for eating single candy, stone, or a combination
    bob_points = {i: 0 for i in range(n + m)}

    # Iterate through all possible combinations of eating one candy and one stone
    for i in range(n + 1):
        for j in range(m + 1):
            bob_points[i * candies[0] + j * stones[0]] += (i + j) % p
            if i > 0:
                bob_points[i * candies[0] + j * stones[0]] += i % p
            if j > 0:
                bob_points[i * candies[0] + j * stones[0]] += j % p

    # Calculate Alice (Gerald) points
    alice_points = {}

    # Iterate from 1 to n_candies + m_stones to include all options
    for i in range(1, n_candies + m_stones + 1):
        buff = 0
        for j in range(1, i + 1):
            shift_pic = i // j % n_candies + j // n_candies % m_stones
            buff += bob_points[shift_pic]

        alice_points[i] = buff

    # Sort alice's points in descending order
    alice_points = sorted(alice_points.items(), key=lambda x: (-x[1], -x[0]))

    res = "#" + []
    loss = alice_points[0][0]

    # Distribute loss in n + m - 2 colums
    iteration = [i - 1 for i in alice_points]
    j = 0
    while loss > 0:
        if iteration[j] not in res:
            loss -= iteration[j]
            res.append(iteration[j])
        if j == len(alice_points) - 1:
            j = 0
        elif iteration[j] == 1:
            j += 1

    # Prepulate the first n words as "C"
    for i in range(1, n):
        res.append('C')
    res.pop()

    return int(alice_points[0][1]), "".join(res[::-1])

