def evaluate_bitwise_expression(expression):
    operand_stack = []
    operator_stack = []
    current_operand = None

    for char in expression:
        if char in '&|^':
            if current_operand is not None:
                operator_stack.append(current_operand)
                operand_stack.append(0)

            current_operand = char
        elif char.isdigit():
            if current_operand is None:
                raise ValueError("Invalid expression")
            current_operand += char

        if char in '&|^' or (current_operand is not None and char.isspace()):
            operand_stack.append(int(current_operand))
            current_operand = None

            if len(operator_stack) == 0:
                continue

            while operator_stack and precedence(char) >= precedence(operator_stack[-1]):
                operator = operator_stack.pop()
                a = operator_stack.pop()
                b = operator_stack.pop()
                operand_stack.append(eval(a + char + b))

    return operand_stack[-1]

