def evaluate_expression(expression):
    """
    Evaluates the given bitwise expression and returns the maximum possible result.
    """
    def apply_operator(operands, operators, pos):
        operand1, operand2 = operands[pos-1], operands[pos+1]
        if operators[pos] == '&':
            return operand1 & operand2
        elif operators[pos] == '|':
            return operand1 | operand2
        elif operators[pos] == '^':
            return operand1 ^ operand2

    expr_result = [int(expression[0])]
    operators_precedence = [12, 8, 2]
    operands_stack = []
    operators_stack = []

    for i, char in enumerate(expression[1:]):
        if char.isdigit():
            expr_result[-1] = expr_result[-1] * 10 + int(char)
        else:
            for _ in range(len(operators_precedence)):
                if operators_precedence[_] <= operators_precedence[-1]:
                    ops_index = operators_precedence.index(_)
                    current_operand = operands_stack.pop()
                    next_operand = operands_stack.pop()
                    operators_stack.pop()
                    operands_stack.append(apply_operator([current_operand, next_operand], operators_stack[ops_index:], i+1))
                else:
                    break

    return operands_stack[0]

