def find_good_cutting_points(tree):
    node_to_parent = {}
    first_found_to = -1
    cutting_point = None
    max_disjoint_trees = -1

    def dfs(node, parent):
        nonlocal first_found_to
        visited.add(node)
        if node in node_to_parent:
            first_found_to = node_to_parent[node]
            cutting_point = node_to_parent[node]
        for neighbor in tree[node]:
            if neighbor not in visited:
                dfs(neighbor, node)
        # Mark node in DFS backtrack
        node_to_parent[node] = cutting_point

    visited = set()
    for node in tree:
        if node not in visited:
            dfs(node, None)

    if cutting_point is None:
        return None, -1

    def calculate_disjoint_trees(root, parent):
        visited_node = set()
        disjoint_trees = 0

        def dfs2(node, parent):
            nonlocal disjoint_trees
            visited_node.add(node)
            if node == root:
                disjoint_trees += 1
            for neighbor in tree[node]:
                if neighbor not in visited_node or node_to_parent[neighbor] == parent:
                    dfs2(neighbor, node)

        dfs2(node, None)
        return disjoint_trees

    disjoint_trees_count = []
    for node in tree:
        if node in visited_node:
            dfs2(node, None)
            disjoint_trees_count.append(disjoint_trees_count.pop() - (parent == cutting_point))
        elif node_to_parent[node] == cutting_point:
            disjoint_trees_count.append(disjoint_trees_count.pop() - 1)

    return cutting_point, max(disjoint_trees_count)

