import sys

def max_value_cola(n, coins, values):
    dp = [[-1 for _ in range(4)] for _ in range(n+1)]

    def dfs(index, total_coins, total_values):
        if index == n + 1:
            return [total_coins, total_values]

        if abs(-(total_values - total_coins) % 2) == 0:
            return [total_coins, total_values]

        if dp[index][total_coins[0]][total_values % 2] != -1:
            return [dp[index][total_coins[0]][total_values % 2]]

        can_add, cant_add = [np.inf for _ in range(len(total_coins))], tot for tot in total_coins

        for i in range(min(n - index + 1, min(can_add) + 1)):
            next_total_coins, next_total_values = dfs(index + i + 1, maximum(coins[index + i]), (total_values + values[index + i]) % 2)
            can_add[i] = min(can_add[i], next_total_coins + 1)
            cant_add[i] = min(cant_add[i], next_total_values)

        curr_dp = [min(can_add) + 1, max(cant_add)]
        if curr_dp[0] <= 0:
            return dp[index][total_coins[0]][total_values % 2] = curr_dp
        else:
            return dp[index][total_coins[0]][total_values % 2] = curr_dp

    max_points = dfs(0, [int(x) for x in coins], [int(x) for x in values])
    return sum(coins[0:max_points[0]]) - sum(values[0:max_points[0]])

