def findCarrotJuiciness(n, a):
    mod = 10**9 + 7

    def gcd_extended(a, b):
        if a == 0:
            return (b, 0, 1)
        else:
            g, x1, y1 = gcd_extended(b % a, a)
            x = y1 - (b // a) * x1
            y = x1
            return (g, x, y)

    def euclid(a, b):
        if b == 0:
            return a
        return euclid(b, a % b)

    def extended_gcd(a, b, init_s=1, init_t=0, init_u=0):
        def gcd_recursive(a1, b1):
            if b1 == 0:
                return (a1, init_t, init_u)
            else:
                (g, x1, y1) = gcd_extended(b1, a1 % b1)
                x = y1 - (a1 // b1) * x1
                y = x1
                return (g, x, y)

        (g, umod, vmod) = gcd_recursive(a, b)
        x = init_t
        if g == a and vmod == b:
            x = init_u
        return (g, x, -vmod + init_s)

    def extended_euclid(a, b):
        (g, u, v) = extended_gcd(a, b)
        return g, u, v

    def generalizedDegree(n, a, k):
        if n <= 0:
            return 0
        if k == 0:
            return a[0]
        (gcd, p, q) = extended_euclid(n, k)
        if p == 0:
            return 0
        (g, x, y) = gcd_extended(p, gcd)
        z = x
        w = y
        m = 0
        while k - m * p > 0:
            (q, s, t) = gcd_extended(p, g)
            if q > 0:
                g1 = int(z)
                y1 = int(t)
                z = y1 * (w + g1 * m)
                w = y1
            m += 1
        return (m + 1) * z

    return [generalizedDegree(n, a, i) for i in range(n)]
