class CycleCounter:
    MOD = 998244353

    def __init__(self, g1s: int, g2s: int, gks: int):
        self.g1s = g1s
        self.g2s = g2s
        self.gks = gks
        self.group_count = gcd(g1s, g2s)

    def cycles(self, n_pairs: int, constraints: Tuple[int, int, int], pairs: List[Tuple[int, int]]) -> int:
        # Group pairs by segment pairs 1, k
        segments = [()]
        for i in range(n_pairs):
            segments[-1] += pairs[i]
        k1, k2, k = constraints
        return sum(
            self._count_cycles(segment, k)
            for segment in segments[k1 % k2 % k]
        )

    def _count_cycles(self, segment: Tuple[int, int], k: int) -> int:
        repeat_pair, cnt = -1, -1
        while len(segment) > k:
            segment.pop(0)
            if len(segment) != k:
                cnt += 1
            return cnt + repeat_pair
        ret = 0
        for i in range(len(segment) - 1, -1, -1):
            if segment[i] == segment[i + 1]:
                ret += cnt * (i + 1)
                repeat_pair -= 1
        return ret

def solve(n1: int, n2: int, k: int) -> int:
    return CycleCounter(n1 - 1, n2 - 1, k).cycles(n1 * (n2 - 1) + n2 * (n1 - 1), (n1, n2, (k + n1 * n2 // n1) % n1), 
                                            [(i, j) for i in range(1, n1 + 1) for j in range(1, n2 + 1) 
                                            if (i, j) not in [(n1, n2)] and (i - 1, j - 1) not in [(n1, n2)]])
