from collections import defaultdict

def dijkstra(tree, start):
    dist = defaultdict(lambda: float('inf'))
    dist[start] = 0
    q = [(0, start)]
    visited = set()

    while q:
        current_dist, current_node = q.pop(0)

        if current_node in visited:
            continue
        visited.add(current_node)

        for neighbor, weight in tree[current_node]:
            if neighbor not in visited:
                new_dist = dist[current_node] + weight
                if new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    q.append((new_dist, neighbor))

    return dist

def solve(n, edges):
    tree = defaultdict(list)
    for start, end in edges:
        tree[start].append((end, 1))
        tree[end].append((start, 1))

    # Construct the networkx graph for DFS
    G = nx.Graph()
    for start, neighbor, weight in edges:
        G.add_edge(start, neighbor, weight=weight)

    # Perform DFS and get distances to all vertices
    dist = nx.single_source_dijkstra(G, 1)

    for i in range(n):
        dist_i = dist[i]
        path_counts = {2: dist_i // 2, 3: dist_i // 3}
        remaining = dist_i % 3

        for height in range(4, remaining + 1):
            if height > remaining:
                continue
            path_count = min(height, remaining - height) // 2 + 1
            if remaining + height >= i * 3:
                path_count += math.ceil((i * 3 - remaining - height) / 2)
            path_counts[height] = path_count

        yield path_counts[max(path_counts.keys())]

# Sample input
