from collections import defaultdict

def findGoodCuttingPoint(root, children):
    visited = {root}
    path_count = 0
    prev_node = None
    for child in children[1:]:
        if child == root:
            path_count += 1
        else:
            count = 0
            while child != root:
                visited.add(child)
                child = children[child][prev_node]
                count += 1
                if child == root:
                    path_count += count
                    break
            prev_node = child
    return path_count

def findPath(root, level_map, parent_map):
    path = defaultdict(int)
    stack = [(root, 1)]
    while stack:
        node, length = stack.pop()
        if length != level_map[node]:
            continue
        level_map[node] = length + 1
        for child in parent_map[node]:
            stack.append((child, length + 1))
    return path

