# Sieve of Eratosthenes to find primes up to N
def sieve(n):
    isPrime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if isPrime[p]:
            for i in range(p * p, n + 1, p):
                isPrime[i] = False
