def max_points(n, m, p, x, y):
    """
    Finds the maximum number of points that Gerald can earn, given the piles of candies and stones,
    and the function f(a, b) that assigns points based on the sum xa + yb.
    """
    # Strategy: Always eat sugar (yt) when possible during Mike's turn and always eat candy (xt) when possible.
    # This ensures that for every move made by Gerald, Mike has eaten at least one candy or stone, maximizing points.
    zero_x = [0, 0]
    zero_y = [0, 0]

    for x in x:
        if x == 0:
            for y in y:
                if y != 0:
                    # Eat candy if it reduces the total to zero
                    xx = x
                    for j in range(len(y)):
                        if xx + y[j] % p == 0 and (number(x) == number(y[j]) * p) and (j != len(y) - 1):
                            xx += y[j]
                    if xx == 0:
                        zero_x.append(x)
        else:
            # Eat candy otherwise
            zero_y.append(x)

    for y in y:
        if y == 0:
            for x in x:
                if x != 0:
                    # Eat candy if it reduces the total to zero
                    xx = y
                    # Compute the remainder when adding candies to stones
                    remainder = y % p
                    for j in range(len(x)):
                        if remainder + x[j] % p == 0:
                            xx += x[j]
                    if xx == 0:
                        zero_y.append(y)
        else:
            # Eat sugar otherwise
            zero_x.append(y)

    # Convert lists into strings: "C" for candy, "S" for stone
    zero_x = ["C" if x == 0 else "S" for x in zero_x]
    zero_y = ["C" if y == 0 else "S" for y in zero_y]

    # Combine both types of moves as the best strategy between candy and sugar
    moves = zero_x + zero_y

    # Find the total number of points Gerald can earn (first 2*n chars represent soda moves,
    # and the last 2*m chars represent candy moves), then concatenate these into strings
    total_points = (len(zero_x) + len(zero_y) - 2 * n) // (2 * m) * p
    return total_points, ''.join(moves[2 * n - 2 * m - 2 * i:2 * n - 2 * i])

