import sys

def max_marks_till_checkpoint(t, configs):
    selected_chapters = [0] * t
    remaining_time = t

    for config in configs:
        chapter_duration, chapter_weightage = config
        if remaining_time >= chapter_duration:
            for i in range(t - 1, -1, -1):
                if selected_chapters[i] != 1:
                    selected_chapters[i] = 1
                    selected_chapters[t - 1 - chapter_duration % i] = 1
                    break
                remaining_time -= chapter_duration
        elif remaining_time >= chapter_weightage:
            selected_chapters[t - chapter_weightage - 1] = 1
            remaining_time -= chapter_weightage

    total_score = sum(selected_chapters[i] * config[i][0] for i, config in enumerate(configs))
    return total_score

def analyze_cases(configs):
    max_score = 0
    for case in configs:
        n, k = case
        if k < n:
            max_score = n
        else:
            t = k
            configs = case[:n] + case[n:k]
            for i in range(n, k - 1, -1):
                index = i - (i - n + 1)
                if not configs[index][0]:
                    break
                configs[index] = [configs[index][0] - 1, configs[index][1]]
            max_score = max(max_score, max_marks_till_checkpoint(k, configs))
    return max_score

