def evaluate_expression(expression):
    stack = []
    operators = {'&': lambda a, b: a & b, '|': lambda a, b: a | b, '^': lambda a, b: a ^ b}

    def apply_operator(op, a, b):
        stack.append(operators[op](a, b))

    for token in expression.split('|'):
        if not token.strip():
            continue
        for operand_str in token.split('&'):
            if not operand_str.strip():
                continue
            stack.append(int(operand_str))
        last_operand = operator = None
        for factor in stack:
            if operator:
                apply_operator(operator, last_operand, factor)
            else:
                operator = factor
            last_operand = factor
        if stack:
            apply_operator(operator, last_operand, stack.pop())

    return stack[-1]

T = int(input())
for _ in range(T):
    expression = input()
    print(evaluate_expression(expression))
