from itertools import combinations

def is_red_triangle(P, Q):
    """
    Check if the points P and Q form a red triangle.
    """
    pq = P - Q
    return all(p*q <= 0 for p in pq)

def is_unbounded(P, Q):
    """
    Check if point Q is unbounded with respect to point P.
    """
    return (P == 0) ^ (Q != P)

def count_unbounded_triangles(red_points, blue_points):
    """
    Count the number of red triangles that do not contain any blue points.
    """
    count = 0
    for L in combinations(red_points, 2):
        for K in combinations(L, 2):
            P, Q = K
            for R in blue_points:
                if is_red_triangle(P, Q) and is_unbounded(R, Q):
                    if any(is_unbounded(R, P) and is_red_triangle(P, Q) and is_unbounded(R, P) 
                           for R in blue_points):
                        continue
                    count += sum([is_unbounded(R, P) 
                                  for R in blue_points])
    return count // 2

# Read input
